  "exp": "正解は1。判例は、内容証明郵便が受取人不在のため配達されず留置期間満了により差出人に還付された事案において、受取人が不在配達通知書によって差出人及び内容を推知することができ、受領の意思があれば容易に受領することができたなどの事情の下では、社会通念上、受取人が了知可能な状態に置かれたものといえ、遅くとも留置期間が満了した時点で意思表示が到達したものと認められるとした(最判平成10年6月11日)。2: 到達とは相手方が知ることができる客観的状態に置かれることをいい、相手方の同居の家族が受領すれば通常は相手方の支配圏内に入ったといえるから、相手方が現実に内容を知らなかったとしても到達は認められる(97条1項)。3: 表意者が通知を発した後に死亡したときであっても、意思表示はそのためにその効力を妨げられない(97条3項)から、解除の意思表示は到達により効力を生じる。4: 相手方が正当な理由なく通知の到達を妨げたときは、通知は通常到達すべきであった時に到達したものとみなされる(97条2項)ので、公示による意思表示をするまでもなく解除の効力を主張できる。なお公示による意思表示は相手方又はその所在を知ることができない場合の方法である(98条1項)。5: 受領能力が問題となるのは、相手方が意思能力を有しなかったとき、未成年者であったとき又は成年被後見人であったときに限られ(98条の2本文)、被保佐人はこれに含まれないから、Aは直ちに対抗することができる。",
